#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
void mainImage(out vec4 O, vec2 C)
{
    vec4 O2=O;




    vec2 u = C;
     vec2 R3 = iResolution.xy,
         U = 9.*u/R3.y, 
         p = U + vec2(-U.y,U),                                             // 45° rotation
         I = ceil(p),                                                      // grid
         f = p - I +.5,                                                    // cell local coordinates
         a = abs(f);                                                       // cell symmetry
 f.x=mod(f.x,4.+cos(iTime));
  f.y=mod(f.y,4.+sin(iTime));
  a.x*=cos(iTime*0.5);
  a.y*=sin(iTime*0.5);

    float d = min(a.x, a.y) - 1.25;                                         // distance to diamond
    int   i = int( I + I.y*3. ) % 5;                                       // diag rotation

    O=  1. - min( abs(d) ,                                                // small diamonds
                   i>3 ? 1e5 : max( abs( (i>0 && i<3 ?-f:f).x + f.y )*.7 , // cross
                                    d )                                    // minus diamonds hole
                 )*R3.xyxy/20.;


            O2=vec4(0);
    vec3 n1,q,r=iResolution,
    d2=normalize(vec3((C*2.-r.xy)/r.y,1));  
    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O2.xyz+=mix(vec3(0.2,.1,3.),H(g*.1),.8)*3./e/8e3
    )
    {
         n1=g*d2;
     n1.x-=iTime;
        a=30.;
         n1=mod( n1-a,a*2.)-a;
        s=2.;
        for(int i=0;i++<8;){
             n1=.3-abs( n1);
             n1.x< n1.z? n1= n1.zyx: n1;
             n1.z< n1.y? n1= n1.xzy: n1;
            s*=e=1.7+sin(iTime*.001)*.1;
             n1=abs( n1)*e-
                vec3(
                    5.+sin(iTime*.03+.05*sin(iTime*.03))*3.,
                    120,
                    8.+cos(iTime*.05)*5.
                 )+O.xyz;
         }
         g+=e=length(n1.yzzz)/s;
    }      
    O=O2;

}
